    [Serializable]
    public sealed class JusticeRuntimeSaveData
    {
        public int schemaVersion = 1; public string worldId; public long revision;
        public CourtRecordData[] courts = Array.Empty<CourtRecordData>(); public ArrestRecordData[] arrests = Array.Empty<ArrestRecordData>(); public CustodyRecordData[] custodyRecords = Array.Empty<CustodyRecordData>(); public ReleaseOrderRecordData[] releaseOrders = Array.Empty<ReleaseOrderRecordData>(); public ChargeRecordData[] charges = Array.Empty<ChargeRecordData>(); public CourtCaseRecordData[] cases = Array.Empty<CourtCaseRecordData>(); public PleaRecordData[] pleas = Array.Empty<PleaRecordData>(); public HearingRecordData[] hearings = Array.Empty<HearingRecordData>(); public EvidenceSubmissionRecordData[] evidenceSubmissions = Array.Empty<EvidenceSubmissionRecordData>(); public ProceduralRulingRecordData[] rulings = Array.Empty<ProceduralRulingRecordData>(); public FindingRecordData[] findings = Array.Empty<FindingRecordData>(); public JudgmentRecordData[] judgments = Array.Empty<JudgmentRecordData>(); public SentenceRecordData[] sentences = Array.Empty<SentenceRecordData>(); public RemedyRecordData[] remedies = Array.Empty<RemedyRecordData>(); public AppealRecordData[] appeals = Array.Empty<AppealRecordData>(); public ClemencyRecordData[] clemencies = Array.Empty<ClemencyRecordData>(); public JusticeTransactionRecordData[] transactions = Array.Empty<JusticeTransactionRecordData>();
        public JusticeRuntimeSaveData Clone() => new JusticeRuntimeSaveData { schemaVersion = Math.Max(1, schemaVersion), worldId = JusticeModelUtility.N(worldId), revision = revision, courts = CloneArray(courts), arrests = CloneArray(arrests), custodyRecords = CloneArray(custodyRecords), releaseOrders = CloneArray(releaseOrders), charges = CloneArray(charges), cases = CloneArray(cases), pleas = CloneArray(pleas), hearings = CloneArray(hearings), evidenceSubmissions = CloneArray(evidenceSubmissions), rulings = CloneArray(rulings), findings = CloneArray(findings), judgments = CloneArray(judgments), sentences = CloneArray(sentences), remedies = CloneArray(remedies), appeals = CloneArray(appeals), clemencies = CloneArray(clemencies), transactions = CloneArray(transactions) };
        private static T[] CloneArray<T>(IEnumerable<T> source) where T : class => (source ?? Array.Empty<T>()).Select(CloneDynamic).Where(item => item != null).ToArray();
        private static T CloneDynamic<T>(T item) where T : class => item switch { CourtRecordData value => value.Clone() as T, ArrestRecordData value => value.Clone() as T, CustodyRecordData value => value.Clone() as T, ReleaseOrderRecordData value => value.Clone() as T, ChargeRecordData value => value.Clone() as T, CourtCaseRecordData value => value.Clone() as T, PleaRecordData value => value.Clone() as T, HearingRecordData value => value.Clone() as T, EvidenceSubmissionRecordData value => value.Clone() as T, ProceduralRulingRecordData value => value.Clone() as T, FindingRecordData value => value.Clone() as T, JudgmentRecordData value => value.Clone() as T, SentenceRecordData value => value.Clone() as T, RemedyRecordData value => value.Clone() as T, AppealRecordData value => value.Clone() as T, ClemencyRecordData value => value.Clone() as T, JusticeTransactionRecordData value => value.Clone() as T, _ => null };
    }

    public sealed class CourtSelectionResult { public CourtSelectionResult(IEnumerable<string> candidateCourts, IEnumerable<string> disqualifiedCourts, string primaryCourtId, IEnumerable<string> conflicts, double evaluationTime, long revision) { CandidateCourtIds = JusticeModelUtility.C(candidateCourts); DisqualifiedCourtIds = JusticeModelUtility.C(disqualifiedCourts); PrimaryCourtId = JusticeModelUtility.N(primaryCourtId); Conflicts = JusticeModelUtility.C(conflicts); EvaluationWorldTime = evaluationTime; SourceRevision = revision; } public IReadOnlyList<string> CandidateCourtIds { get; } public IReadOnlyList<string> DisqualifiedCourtIds { get; } public string PrimaryCourtId { get; } public IReadOnlyList<string> Conflicts { get; } public double EvaluationWorldTime { get; } public long SourceRevision { get; } public bool Resolved => !string.IsNullOrEmpty(PrimaryCourtId) && Conflicts.Count == 0; }
    public sealed class JusticeOperationResult { public bool Succeeded { get; private set; } public JusticeOperationCode Code { get; private set; } public bool Preview { get; private set; } public bool Duplicate { get; private set; } public string SubjectId { get; private set; } public string Message { get; private set; } public long RevisionBefore { get; private set; } public long RevisionAfter { get; private set; } public static JusticeOperationResult Success(string message, long before, long after, string subject = "", bool preview = false, bool duplicate = false) => new JusticeOperationResult { Succeeded = true, Code = preview ? JusticeOperationCode.Preview : duplicate ? JusticeOperationCode.Duplicate : JusticeOperationCode.Succeeded, Preview = preview, Duplicate = duplicate, SubjectId = subject ?? string.Empty, Message = message ?? string.Empty, RevisionBefore = before, RevisionAfter = after }; public static JusticeOperationResult Failure(JusticeOperationCode code, string message, long revision) => new JusticeOperationResult { Succeeded = false, Code = code, Message = message ?? string.Empty, RevisionBefore = revision, RevisionAfter = revision }; }
    public sealed class JusticeProjectionResult<TRecord> where TRecord : class { public bool Succeeded { get; private set; } public bool Redacted { get; private set; } public JusticeVisibilityDecision Decision { get; private set; } public TRecord Record { get; private set; } public string Message { get; private set; } public static JusticeProjectionResult<TRecord> Success(TRecord record, bool redacted, string message) => new JusticeProjectionResult<TRecord> { Succeeded = true, Redacted = redacted, Decision = redacted ? JusticeVisibilityDecision.RedactedAccess : JusticeVisibilityDecision.FullAccess, Record = record, Message = message ?? string.Empty }; public static JusticeProjectionResult<TRecord> Denied(string message, JusticeVisibilityDecision decision = JusticeVisibilityDecision.Denied) => new JusticeProjectionResult<TRecord> { Decision = decision, Message = message ?? string.Empty }; }
